/**
 * Autogenerated File:
 * Compiles the Tailwind entry points in src/ into dist/:
 *   src/styles.css          -> dist/styles.css          (@repo/ui/styles.css)
 *   src/<component>/styles.css -> dist/<component>/styles.css (@repo/ui/<component>/styles.css)
 *
 * The output has no preflight and no @layer blocks, so the library's prefixed utilities compete with
 * an app's CSS by normal specificity and source order instead of always losing to unlayered app CSS.
 */
import { mkdir, readdir, readFile, writeFile } from 'node:fs/promises';
import { dirname, join, relative } from 'node:path';
import { fileURLToPath } from 'node:url';
import postcss from 'postcss';
import tailwindcss from '@tailwindcss/postcss';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const src = join(root, 'src');
const dist = join(root, 'dist');

/** Replaces every `@layer name { … }` block with its contents and drops `@layer a, b;` statements. */
const unwrapLayers = {
  postcssPlugin: 'pcgl-unwrap-layers',
  OnceExit(css) {
    css.walkAtRules('layer', (rule) => {
      if (rule.nodes) rule.replaceWith(rule.nodes);
      else rule.remove();
    });
  },
};

/**
 * `prefix(pcgl)` covers utilities and theme variables, but Tailwind still emits two global names:
 * its internal `--tw-*` properties (registered with @property for the whole page) and @keyframes
 * such as `spin`. Rename both into the pcgl namespace so they can't clash with an app's CSS.
 */
const namespaceGlobals = {
  postcssPlugin: 'pcgl-namespace-globals',
  OnceExit(css) {
    const keyframes = new Set();
    css.walkAtRules('keyframes', (rule) => {
      if (!rule.params.startsWith('pcgl-')) {
        keyframes.add(rule.params);
        rule.params = `pcgl-${rule.params}`;
      }
    });
    const renameKeyframes = (value) =>
      [...keyframes].reduce(
        (result, name) =>
          result.replace(new RegExp(`(^|[\\s,])${name}(?=[\\s,]|$)`, 'g'), `$1pcgl-${name}`),
        value,
      );
    css.walkAtRules('property', (rule) => {
      rule.params = rule.params.replace(/^--tw-/, '--pcgl-tw-');
    });
    css.walkDecls((decl) => {
      decl.prop = decl.prop.replace(/^--tw-/, '--pcgl-tw-');
      decl.value = decl.value.replaceAll('--tw-', '--pcgl-tw-');
      if (/^(animation(-name)?|--pcgl-animate-.*)$/.test(decl.prop)) {
        decl.value = renameKeyframes(decl.value);
      }
    });
  },
};

const entries = [join(src, 'styles.css')];
for (const entry of await readdir(src, { withFileTypes: true })) {
  if (!entry.isDirectory()) continue;
  const candidate = join(src, entry.name, 'styles.css');
  try {
    await readFile(candidate);
    entries.push(candidate);
  } catch {
    // component without its own stylesheet
  }
}

const processor = postcss([
  tailwindcss({ base: src, optimize: { minify: true } }),
  unwrapLayers,
  namespaceGlobals,
]);

for (const from of entries) {
  const to = join(dist, relative(src, from));
  const result = await processor.process(await readFile(from, 'utf8'), { from, to });
  await mkdir(dirname(to), { recursive: true });
  await writeFile(to, result.css);
  console.log(
    `${relative(root, to)}  ${(new TextEncoder().encode(result.css).length / 1024).toFixed(1)} KiB`,
  );
}
